add(r'iX', r'X', [r'index:X', r'\mathrm{L}', r'\mathrm{R}'], r'The label of a half of dirac16complex: $X \in \{\mathrm{L}, \mathrm{R}\}$ (left-handed or right-handed half); a sum over $X$ runs over both.', '', '', r'STANDARD')
add(r'if', r'f', [r'index:f'], r'The label of a kind of Standard-Model multiplet: $f \in \{Q, u, d, \ell, e, \nu\}$ (quark doublets, up-quark singlets, down-quark singlets, lepton doublets, charged-lepton singlets, right-handed neutrinos); a sum over $f$ runs over the six.', '', '', r'STANDARD')
add(r'ipsi', r'\psi', [r'index:\psi'], r'The label of a Standard-Model fermion field in a sum: $\psi$ runs over $Q, u_{\mathrm{R}}, d_{\mathrm{R}}, \ell, e_{\mathrm{R}}, \nu_{\mathrm{R}}$.', '', '', r'STANDARD')
add(r'ir', r'r', [r'index:r'], r'An extra-time direction of the fold: $r \in \{5, 6, 7\}$ ($x_5, x_6, x_7$); not summed (the three components are equal).', '', '', r'STANDARD')
add(r'io', r'o', [r'index:o'], r'The label of a single-particle state of dirac16complex: a Kohn-Sham orbital, or a mode of the quantised field; a sum over $o$ runs over the orbitals or the modes.', '', '', r'STANDARD')
add(r'Xcoord', r'X = \{x_0, \dots, x_7\}', [r'X'], r"The author's coordinates of the eight-dimensional spacetime, $X = \{x_0, x_1, \dots, x_7\}$ with the hidden direction first (Dirac_Einstein-Lovelock_4+4_Nash.nb, section DEFCHART); $X^M$ is the coordinate with the index $M$ and $\mathrm{d}^8X = \mathrm{d}x_0\,\mathrm{d}x_1\cdots\mathrm{d}x_7$ the coordinate volume element.", r'length (each coordinate)', '', r'AUTHOR')
add(r'xfour', r'x', [r'x'], r'The coordinates of the fold: $x_1, x_2, x_3$ of ordinary space, $x_4$ the time, $x_5, x_6, x_7$ the extra times; a field of the fold is a function of the four observable coordinates $x = (x_1, x_2, x_3, x_4)$, and $\mathrm{d}^4x = \mathrm{d}x_1\,\mathrm{d}x_2\,\mathrm{d}x_3\,\mathrm{d}x_4$.', r'length (each coordinate)', '', r'AUTHOR')
add(r'x0', r'x_0', [r'x_{0}'], r'The hidden space-like coordinate (listed first); the metric depends on it through $z = 6Hx_0$, periodically with the period $\pi/(6H)$.', r'length', '', r'AUTHOR')
add(r'x1', r'x_1', [r'x_{1}'], r'The first coordinate of ordinary 3-space.', r'length', '', r'AUTHOR')
add(r'x2', r'x_2', [r'x_{2}'], r'The second coordinate of ordinary 3-space.', r'length', '', r'AUTHOR')
add(r'x3', r'x_3', [r'x_{3}'], r'The third coordinate of ordinary 3-space.', r'length', '', r'AUTHOR')
add(r'x4', r'x_4', [r'x_{4}'], r'The time; a prime on a function of $x_4$ alone is $\mathrm{d}/\mathrm{d}x_4$.', r'length (= time, $c = 1$)', '', r'AUTHOR')
add(r'x5', r'x_5', [r'x_{5}'], r'The first of the three extra time-like coordinates.', r'length', '', r'AUTHOR')
add(r'x6', r'x_6', [r'x_{6}'], r'The second of the three extra time-like coordinates.', r'length', '', r'AUTHOR')
add(r'x7', r'x_7', [r'x_{7}'], r'The third of the three extra time-like coordinates.', r'length', '', r'AUTHOR')
add(r'sigma', r'\sigma', [r'\sigma'], r'The proper coordinate of the hidden direction: $\mathrm{d}\sigma = \lvert\cot z\rvert\,\mathrm{d}x_0$, $\sigma = \mathrm{sgn}(\pi/2 - z)\ln(\sin z)/(6H)$ on one period $0 < z < \pi$; $\sigma = 0$ is the fold $z = \pi/2$, $\sigma \to \mp\infty$ the tips $z \to 0, \pi$; one period of $x_0$ is the whole line $-\infty < \sigma < \infty$.', r'length', '', r'DERIVED')
add(r'zvar', r'z', [r'z'], r'The angle variable of the hidden direction, $z = 6Hx_0$; one period of $x_0$ is $0 < z < \pi$, the fold is $z = \pi/2$.', r'dimensionless', '', r'AUTHOR')
add(r'metric', r'g_{MN}', [r'g'], r'The metric tensor of the eight-dimensional spacetime (signature $+,+,+,+,-,-,-,-$ in the order $x_0, \dots, x_7$): $g_{MN}\,\mathrm{d}X^M\mathrm{d}X^N$ is the squared interval, $g^{MN}$ its inverse, $\lvert g\rvert$ the absolute value of its determinant ($\sqrt{\lvert g\rvert}\,\mathrm{d}^8X$ is the proper volume element).', r'dimensionless', '', r'AUTHOR')
add(r'eta', r'\eta_{ab}', [r'\eta'], r'The flat metric of the frame, $\eta = \mathrm{diag}(1, 1, 1, 1, -1, -1, -1, -1)$ (eta4488 of 4+4.nb); $\eta^{ab}$ is its inverse (the same matrix).', r'dimensionless', '', r'AUTHOR')
add(r'vielbein', r'\mathbf{e}_a{}^M,\ \mathbf{e}^a{}_M', [r'\mathbf{e}'], r'The vielbein (frame field) of the metric: $g_{MN} = \eta_{ab}\,\mathbf{e}^a{}_M\mathbf{e}^b{}_N$; $\mathbf{e}_a{}^M$ is its inverse; $\mathbf{e}_{bN} = \eta_{bc}\mathbf{e}^c{}_N$; $\mathbf{e}^{(a)}$ is the frame one-form $\mathbf{e}^a{}_M\,\mathrm{d}X^M$.', r'dimensionless', '', r'STANDARD')
add(r'Christoffel', r'\Gamma^P{}_{MN}', [r'\Gamma'], r'The Christoffel symbols of the metric $g_{MN}$ (the Levi-Civita connection).', r'1/length', '', r'STANDARD')
add(r'Riemann', r'R^{MN}{}_{PQ},\ R_{MN},\ R', [r'R'], r'The curvature of the metric $g_{MN}$: with four indices the Riemann tensor $R^M{}_{NPQ}$ (in the convention in which the commutator of two covariant derivatives, acting on a vector, is the Riemann tensor, with its last two indices those of the two derivatives, contracted with the vector), with two indices the Ricci tensor $R_{MN} = R^P{}_{MPN}$, without indices the scalar curvature $R = g^{MN}R_{MN}$; with frame indices $R^{(a)(b)}{}_{(c)(d)}$ its frame components, $R^{(a)(b)}{}_{(a)(b)}$ (no sum) the sectional curvature of the frame plane $(a, b)$.', r'1/length$^2$', '', r'STANDARD')
add(r'Hconst', r'H', [r'H'], r"The author's constant (an inverse length) that fixes the period $\pi/(6H)$ of $x_0$, the warp factor $\mathrm{e}^{-2H\lvert\sigma\rvert}$ of the metric, the cosmological constant $\Lambda = -21H^2$ and the tension $\kappa\lambda_{\mathrm{F}} = 12H$ of the fold; in UM-4 a free parameter, bounded from below by the propagation of the gauge fields in the bulk.", r'GeV (1/length)', r'$H \gtrsim 2.5$ TeV (from the invisible width of the Z boson)', r'AUTHOR')
add(r'a4', r'a_4', [r'a_{4}'], r"The author's metric function of the time $x_4$ that scales ordinary 3-space: on the fold $\mathrm{e}^{a_4}$ is the scale factor of cosmology and $a_4'$ the Hubble rate.", r'dimensionless', '', r'AUTHOR')
add(r'b4', r'b_4', [r'b_{4}'], r"The author's metric function of the time $x_4$ in the extra-time components, $b_4 > 0$, never identically 1 (the author's order of 2026-10-24); the scale factor (the factor of the lengths) of the extra times is $\mathrm{e}^{-a_4}b_4$ on the fold and $\mathrm{e}^{-a_4}b_4\,\mathrm{e}^{-H\lvert\sigma\rvert}$ at the distance $\sigma$ from it (the square root of the warp factor times $\mathrm{e}^{-a_4}b_4$).", r'dimensionless', '', r'AUTHOR')
add(r'Stot', r'S_{\mathrm{tot}}', [r'S_{\mathrm{tot}}'], r'The action of UM-4 (the integral of the Lagrangian density over spacetime); its variation with respect to every field gives the field equations.', r'dimensionless (in units in which the reduced Planck constant is 1)', '', r'ASSUMED')
add(r'SEL', r'S_{\mathrm{EL}}', [r'S_{\mathrm{EL}}'], r'The Einstein-Lovelock action of gravity in eight dimensions; in UM-4 the Einstein-Hilbert action with the cosmological constant.', r'dimensionless', '', r'AUTHOR')
add(r'SPsi', r'S_\Psi', [r'S_{\Psi}'], r'The action of dirac16complex in the bulk (kinetic term with the canonical spin connection, mass term, contact self-interaction).', r'dimensionless', '', r'RECORD')
add(r'Sfold', r'S_{\mathrm{fold}}', [r'S_{\mathrm{fold}}'], r'The action of the fold: the Standard Model, the portals of dirac16complex, the fold fluid and the Einstein-Hilbert term that the fields of the fold induce, all at $\sigma = 0$.', r'dimensionless', '', r'ASSUMED')
add(r'kappa', r'\kappa', [r'\kappa'], r'The eight-dimensional gravitational coupling, $\kappa = 8\pi G_8$.', r'GeV$^{-6}$', '', r'AUTHOR')
add(r'G8', r'G_8', [r'G_{8}'], r'The eight-dimensional Newton constant ($\kappa = 8\pi G_8$).', r'GeV$^{-6}$', '', r'AUTHOR')
add(r'alphaL', r'\alpha_{(p)}', [r'\alpha'], r'The Lovelock coupling of order $p$, $\alpha_{(p)} = w_{(p)}H^{2-2p}$: in UM-4 $\alpha_{(1)} = 1$ and $\alpha_{(2)} = \alpha_{(3)} = 0$ (Einstein gravity).', r'GeV$^{2-2p}$', '', r'AUTHOR')
add(r'wL', r'w_{(p)}', [r'w'], r"The Lovelock weights of the author's Einstein-Lovelock action, $w_{(1)} = 1$ and $w_{(2)}$, $w_{(3)}$ of the Gauss-Bonnet and the cubic densities. UM-4 sets $w_{(2)} = w_{(3)} = 0$ (Einstein gravity): the only weights for which gravitons propagate on the light cone on every background, not only around the static block. The author's original weights $w_{(2)} = 1/32$, $w_{(3)} = 1/1152$ (Dirac_Einstein-Lovelock_4+4_Nash.nb, In[134]) keep the gravitons on the light cone only around the static block (with $\Lambda = -161H^2/16$); UM-3 used $(1, 1/20, 1/360)$.", r'dimensionless', r"$(1, 0, 0)$ in UM-4; the author's original $(1, 1/32, 1/1152)$", r'AUTHOR (the form), DERIVED (the values that the order of 2026-10-25 selects)')
add(r'ctw', r'c_{\mathrm{t}}', [r'c_{\mathrm{t}}'], r'The coefficient of the second derivative along the proper time in the linearised equation of a gravitational wave of the + polarisation on a static warped background, normalised so that Einstein gravity gives 1.', r'dimensionless', r'1 for Einstein gravity on every background; $1 - 40w_{(2)} + 360w_{(3)}$ at the static block of UM-3', r'DERIVED')
add(r'cxw', r'c_{\mathrm{x}}', [r'c_{\mathrm{x}}'], r'The coefficient of the second derivative along the proper length of $x_3$ in the same equation; the wave moves along $x_3$ with the local speed $\sqrt{c_{\mathrm{x}}/c_{\mathrm{t}}}$ in units of the local speed of light.', r'dimensionless', r"1 for Einstein gravity on every background; $1 - 24w_{(2)} + 72w_{(3)}$ at the static block of UM-3 ($c_{\mathrm{x}}/c_{\mathrm{t}} = 5$ with the author's original weights)", r'DERIVED')
add(r'ycurv', r'\mathsf{y}', [r'\mathsf{y}'], r'The curvature of a static block of constant curvature $-\mathsf{y}H^2$ in all eight directions, in units of $-H^2$ (its warp is $\mathrm{e}^{-2\sqrt{\mathsf{y}}H\lvert\sigma\rvert}$ in all seven directions of the fold): $\mathsf{y} = 1$ is the static block of UM-4.', r'dimensionless', '', r'DERIVED')
add(r'LovL', r'\mathcal{L}_{(p)}', [r'\mathcal{L}'], r'The Lovelock density of order $p$, $\mathcal{L}_{(p)} = 2^{-p}\,\delta^{P_1\cdots P_{2p}}_{Q_1\cdots Q_{2p}}\,R^{Q_1Q_2}{}_{P_1P_2}\cdots R^{Q_{2p-1}Q_{2p}}{}_{P_{2p-1}P_{2p}}$, a scalar built from $p$ curvature tensors: $\mathcal{L}_{(1)} = R$ (Einstein-Hilbert), $\mathcal{L}_{(2)}$ the Gauss-Bonnet density, $\mathcal{L}_{(3)}$ the cubic Lovelock density.', r'1/length$^{2p}$', '', r'STANDARD')
add(r'Lambda', r'\Lambda', [r'\Lambda'], r'The eight-dimensional cosmological constant of UM-4, $\Lambda = -21H^2$: the value for which the static block is a vacuum of Einstein gravity (its Einstein tensor is $21H^2$ in every direction). The author writes the pure number $\Lambda_{\mathrm{N}}$ in $0 = -\Lambda_{\mathrm{N}} + \sum_p H^{-2p}w_{(p)}\mathcal{E}_{(p)}$, so that $\Lambda = -\Lambda_{\mathrm{N}}H^2$.', r'GeV$^2$', r"$-21H^2$; the author's original $-10H^2$; UM-3: $-7H^2$", r'AUTHOR (the term), DERIVED (the value)')
add(r'LambdaN', r'\Lambda_{\mathrm{N}}', [r'\Lambda_{\mathrm{N}}'], r"The author's pure number in the vacuum equations of his notebook, $\Lambda = -\Lambda_{\mathrm{N}}H^2$: his original value 10; 21 in UM-4 (Einstein gravity), 7 in UM-3.", r'dimensionless', r"21 (the author's original 10)", r'AUTHOR')
add(r'Psi', r'\Psi,\ \bar\Psi', [r'\Psi', r'\bar{\Psi}'], r"dirac16complex: the author's 16-component complex spinor field of eight dimensions; $\bar\Psi = \Psi^\dagger\sigma_{16}$ is its Dirac adjoint; in a term of the fold, $\Psi$ is its value at $\sigma = 0$.", r'GeV$^{7/2}$', '', r'AUTHOR')
add(r'PsiL', r'\Psi_{\mathrm{L}}', [r'\Psi_{\mathrm{L}}'], r'The left-handed half of dirac16complex, $\Psi_{\mathrm{L}} = P_{\mathrm{L}}\Psi$ (the upper eight components in the basis of 4+4.nb).', r'GeV$^{7/2}$', '', r'AUTHOR')
add(r'PsiR', r'\Psi_{\mathrm{R}}', [r'\Psi_{\mathrm{R}}'], r'The right-handed half of dirac16complex, $\Psi_{\mathrm{R}} = P_{\mathrm{R}}\Psi$ (the lower eight components).', r'GeV$^{7/2}$', '', r'AUTHOR')
add(r'Tmat', r'T_a,\ T^a', [r'T', r'T_{0}', r'T_{1}', r'T_{2}', r'T_{3}', r'T_{4}', r'T_{5}', r'T_{6}', r'T_{7}'], r"The author's eight real $16 \times 16$ Dirac matrices T16^A[a] of 4+4.nb ($a = 0, \dots, 7$; $T_0, \dots, T_7$), with $\{T_a, T_b\} = 2\eta_{ab}\mathbf{1}$; $T^a = \eta^{ab}T_b$.", r'dimensionless', '', r'AUTHOR')
add(r'gammaM', r'\gamma^M,\ \gamma^{(a)}', [r'\gamma'], r'The Dirac matrices of dirac16complex along the coordinates, $\gamma^M = \mathbf{e}_a{}^MT^a$, $\gamma_M = g_{MN}\gamma^N$; $\gamma^{(a)} = T^a$ along the frame direction $(a)$ ($\gamma^{(0)}$ along $\sigma$, $\gamma^{(4)}$ along the time).', r'dimensionless', '', r'AUTHOR')
add(r'sigma16', r'\sigma_{16}', [r'\sigma_{16}'], r'The matrix of the Dirac adjoint, $\sigma_{16} = T_0T_1T_2T_3$, real and symmetric; $\sigma_{16}T_a$ is real and antisymmetric.', r'dimensionless', '', r'AUTHOR')
add(r'Gamma8', r'\Gamma_8', [r'\Gamma_{8}'], r"The chirality matrix of eight dimensions, $\Gamma_8 = T_0T_1\cdots T_7$ (the author's T16^A[8]) $= \mathrm{diag}(-\mathbf{1}_8, \mathbf{1}_8)$; $\Gamma_8^2 = \mathbf{1}$; it anticommutes with every $T_a$.", r'dimensionless', '', r'AUTHOR')
add(r'PL', r'P_{\mathrm{L}}', [r'P_{\mathrm{L}}'], r"The author's left-handed chiral projector, $P_{\mathrm{L}} = (\mathbf{1} - \Gamma_8)/2$.", r'dimensionless', '', r'AUTHOR')
add(r'PR', r'P_{\mathrm{R}}', [r'P_{\mathrm{R}}'], r"The author's right-handed chiral projector, $P_{\mathrm{R}} = (\mathbf{1} + \Gamma_8)/2$.", r'dimensionless', '', r'AUTHOR')
add(r'PX', r'P_X', [r'P'], r'The chiral projector of the half $X$: $P_X = P_{\mathrm{L}}$ for $X = \mathrm{L}$, $P_{\mathrm{R}}$ for $X = \mathrm{R}$.', r'dimensionless', '', r'AUTHOR')
add(r'Dcov', r'D_M,\ D_\mu', [r'D'], r'The covariant derivative: on dirac16complex $D_M = \partial_M + \Omega_M$ (with $D_M\bar\Psi = \partial_M\bar\Psi - \bar\Psi\Omega_M$); on the fields of the fold the gauge and spin covariant derivative $D_\mu$ (the partial derivative plus the spin connection of the fold and the gauge fields times their couplings and generators); $D^\mu = \hat h^{\mu\nu}D_\nu$; on an adjoint field $(D_\mu X)^A = \partial_\mu X^A + g_3f^{ABC}G^B_\mu X^C$ (likewise for $SU(2)$ with $g_2\epsilon^{IJK}$).', r'1/length', '', r'STANDARD')
add(r'mPsi', r'm_\Psi', [r'm_{\Psi}'], r'The mass parameter of dirac16complex in the bulk.', r'GeV', '', r'RECORD')
add(r'lamPsi', r'\lambda_\Psi', [r'\lambda_{\Psi}'], r'The coupling of the contact self-interaction of dirac16complex.', r'GeV$^{-6}$', '', r'RECORD')
add(r'Omega', r'\Omega_M', [r'\Omega'], r'The spin connection acting on dirac16complex, $\Omega_M = \frac12\varpi_{Mab}\Sigma^{ab}$.', r'1/length', '', r'RECORD')
add(r'omegaSC', r'\varpi_{Mab}', [r'\varpi'], r'The canonical (Levi-Civita) spin connection of the vielbein, antisymmetric in $a, b$.', r'1/length', '', r'STANDARD')
add(r'SigmaGen', r'\Sigma^{ab},\ \Sigma^{\mu\nu}', [r'\Sigma'], r"The generators of Spin(4,4) on dirac16complex, $\Sigma^{ab} = \frac14[T^a, T^b]$ (the scaled commutators of the author's matrices); $\Sigma^{\mu\nu} = \mathbf{e}_a{}^\mu\mathbf{e}_b{}^\nu\Sigma^{ab}$ along the fold.", r'dimensionless', '', r'AUTHOR')
add(r'Vstar', r'V_*', [r'V_{*}'], r'The physical volume of the extra times $x_5, x_6, x_7$ on the fold in the late universe, $V_* = V_{\mathrm{t}}(\mathrm{e}^{-a_4}b_4)^3$ (with $V_{\mathrm{t}} = \int\mathrm{d}x_5\,\mathrm{d}x_6\,\mathrm{d}x_7$ the coordinate volume of the extra times) at a time when $\mathrm{e}^{-a_4}b_4$ is constant; it converts the eight-dimensional normalisation into the four-dimensional one.', r'length$^3$ (GeV$^{-3}$)', '', r'ASSUMED')
add(r'Vt', r'V_{\mathrm{t}}', [r'V_{\mathrm{t}}'], r'The coordinate volume of the (compact) extra times, $V_{\mathrm{t}} = \int\mathrm{d}x_5\,\mathrm{d}x_6\,\mathrm{d}x_7$.', r'length$^3$', '', r'ASSUMED')
add(r'Zfold', r'\mathcal{Z}', [r'\mathcal{Z}'], r'The fold factor, $\mathcal{Z}(x_4) = V_{\mathrm{t}}(\mathrm{e}^{-a_4}b_4)^3/V_*$: the factor by which the size of the extra times multiplies every term of the fold and the kinetic terms of the massless modes of the fields of the bulk; $\mathcal{Z} = 1$ when the extra times are frozen at their late value.', r'dimensionless', r'1 in the late universe', r'DERIVED')
add(r'Ffold', r'\mathbb{F}', [r'\mathbb{F}'], r'Any function of the fields at the fold (used to state a rule of integration).', '', '', r'STANDARD')
add(r'hhat', r'\hat h_{\mu\nu}', [r'\hat{h}'], r'The four-dimensional metric of the fold, $\hat h_{\mu\nu} = \mathrm{diag}(\mathrm{e}^{2a_4}, \mathrm{e}^{2a_4}, \mathrm{e}^{2a_4}, -1)$ in the coordinates $x_1, \dots, x_4$ (the induced metric at $\sigma = 0$ without the extra times); $\hat h^{\mu\nu}$ its inverse, $\hat h$ its determinant, $\sqrt{-\hat h} = \mathrm{e}^{3a_4}$; $\hat h^{(1)}_{\mu\nu}$ its first-order cosmological perturbation.', r'dimensionless', '', r'DERIVED')
add(r'Rhat', r'\hat R', [r'\hat{R}'], r'The curvature of the metric $\hat g_{ab}$ of the fold (FD-2): with four frame indices its Riemann tensor, with two its Ricci tensor $\hat R_{ab}$, without indices its scalar curvature $\hat R$; for frozen extra times the scalar curvature equals that of the four-dimensional metric $\hat h_{\mu\nu}$.', r'1/length$^2$', '', r'STANDARD')
add(r'kappa7', r'\kappa_7', [r'\kappa_{7}'], r'The gravitational coupling of the fold: to the first order in its curvature over $H^2$ the fold obeys the Einstein equations of seven dimensions $\hat G^a{}_b = \kappa_7\mathsf{t}^a{}_b$ with $\kappa_7 = 5\kappa H/2$, the coupling of the massless graviton of the bulk bound to the fold; four-dimensional gravity on the fold has $8\pi G_{\mathrm{N}} = \kappa_7/V_*$ (plus the induced term, which is negligible).', r'GeV$^{-5}$', r'$5\kappa H/2$', r'DERIVED')
add(r'kappaind', r'\kappa_{\mathrm{ind}}', [r'\kappa_{\mathrm{ind}}'], r'The coupling of the Einstein-Hilbert term $\hat R/(2\kappa_{\mathrm{ind}})$ that the quantum fluctuations of the fields of the fold may induce, $\kappa_{\mathrm{ind}} = 8\pi G_{\mathrm{ind}}$; it adds to the gravity of the fold, $1/(8\pi G_{\mathrm{N}}) = V_*/\kappa_7 + 1/\kappa_{\mathrm{ind}}$.', r'GeV$^{-2}$', r'not fixed by UM-4; negligible for a cutoff of the order of $H$', r'ESTIMATE')
add(r'LIG', r'\mathcal{L}_{\mathrm{IG}}', [r'\mathcal{L}_{\mathrm{IG}}'], r'The Lagrangian of the Einstein-Hilbert term of the four-dimensional metric of the fold that the quantum fluctuations of the fields of the fold induce; it adds to the Einstein-Hilbert term that the graviton of the bulk gives the fold and does not change the speed of gravitational waves.', r'GeV$^4$', '', r'ESTIMATE')
add(r'Lff', r'\mathcal{L}_{\mathrm{ff}}', [r'\mathcal{L}_{\mathrm{ff}}'], r'The Lagrangian of the fold fluid (only its energy-momentum tensor $\mathcal{T}_{\mathrm{ff}}$ enters the equations).', r'GeV$^4$', '', r'ASSUMED')
add(r'Tff', r'\mathcal{T}_{\mathrm{ff}}{}^a{}_b', [r'\mathcal{T}_{\mathrm{ff}}'], r'The energy-momentum tensor of the fold fluid (frame components of the fold, four-dimensional normalisation).', r'GeV$^4$', '', r'ASSUMED')
add(r'rhoff', r'\rho_{\mathrm{ff}}', [r'\rho_{\mathrm{ff}}'], r'The energy density of the fold fluid.', r'GeV$^4$', r'$\lambda_{\mathrm{F}}V_* + \rho_\Lambda - \rho_{\mathrm{vac}}$: together with the vacuum energy $\rho_{\mathrm{vac}}$ of the fields of the fold it makes up the tension $\lambda_{\mathrm{F}}V_*$ that the static block requires plus the dark energy $\rho_\Lambda$', r'ASSUMED (the fluid), DERIVED (the value)')
add(r'pff', r'p_{\mathrm{ff}}', [r'p_{\mathrm{ff}}'], r'The pressure of the fold fluid along ordinary space.', r'GeV$^4$', r'$-\rho_{\mathrm{ff}}$ (a tension)', r'ASSUMED (the fluid), DERIVED (the value)')
add(r'qff', r'q_{\mathrm{ff}}', [r'q_{\mathrm{ff}}'], r'The pressure of the fold fluid along the extra times: minus its energy density (its tension) plus the pressure $q_{\mathrm{hold}}$ that holds the volume of the extra times fixed.', r'GeV$^4$', r'$-\rho_{\mathrm{ff}} + q_{\mathrm{hold}}$', r'ASSUMED (the fluid), DERIVED (the value)')
add(r'LH', r'\mathcal{L}_{\mathrm{H}}', [r'\mathcal{L}_{\mathrm{H}}'], r'The Lagrangian of the Higgs doublet on the fold.', r'GeV$^4$', '', r'AUTHOR')
add(r'Lgauge', r'\mathcal{L}_{\mathrm{gauge}}', [r'\mathcal{L}_{\mathrm{gauge}}'], r'The Lagrangian of the gauge fields of $SU(3)_C\times SU(2)_L\times U(1)_Y$ in the bulk.', r'GeV$^8$', '', r'STANDARD')
add(r'Lf', r'\mathcal{L}_{\mathrm{f}}', [r'\mathcal{L}_{\mathrm{f}}'], r'The kinetic Lagrangian of the quarks and leptons on the fold.', r'GeV$^4$', '', r'STANDARD')
add(r'LY', r'\mathcal{L}_{\mathrm{Y}}', [r'\mathcal{L}_{\mathrm{Y}}'], r'The Yukawa Lagrangian of the quarks and leptons with the Higgs doublet.', r'GeV$^4$', '', r'STANDARD')
add(r'LP', r'\mathcal{L}_{\mathrm{P}}', [r'\mathcal{L}_{\mathrm{P}}'], r'The Lagrangian of the portals of dirac16complex at the fold.', r'GeV$^4$', '', r'INVENTED')
add(r'Phi', r'\Phi', [r'\Phi'], r'The Higgs doublet (two complex components, hypercharge $1/2$), a field of the fold.', r'GeV', '', r'AUTHOR')
add(r'Phitilde', r'\tilde\Phi', [r'\tilde{\Phi}'], r'The conjugate Higgs doublet, $\tilde\Phi = \mathrm{i}\tau^2\Phi^*$ (hypercharge $-1/2$).', r'GeV', '', r'STANDARD')
add(r'Vpot', r'V(\Phi)', [r'V'], r'The Higgs potential, $V = \mu^2\Phi^\dagger\Phi + \lambda(\Phi^\dagger\Phi)^2$.', r'GeV$^4$', '', r'AUTHOR')
add(r'muH', r'\mu^2', [r'\mu'], r'The mass parameter of the Higgs potential, $\mu^2 < 0$ (it enters only as $\mu^2$).', r'GeV$^2$', r'$\mu^2 = -\lambda v^2 = -m_h^2/2 = -(88.6\ \mathrm{GeV})^2$', r'AUTHOR')
add(r'lamH', r'\lambda', [r'\lambda'], r'The quartic coupling of the Higgs potential, $\lambda > 0$.', r'dimensionless', r'$\lambda = m_h^2/(2v^2) = 0.129$', r'AUTHOR')
add(r'vev', r'v', [r'v'], r'The vacuum expectation value of the lower component of the Higgs doublet, $v^2 = -\mu^2/\lambda$.', r'GeV', r'246.22 GeV $= (\sqrt2\,G_{\mathrm{F}})^{-1/2}$ with the Fermi constant $G_{\mathrm{F}} = 1.1663788\times10^{-5}$ GeV$^{-2}$ of the muon lifetime (Particle Data Group)', r'STANDARD')
add(r'hHiggs', r'h', [r'h'], r'The Higgs field: the fluctuation of the lower component of the Higgs doublet about $v$.', r'GeV', r'$m_h = 125.25$ GeV', r'STANDARD')
