add(r'qdecay', r'q', [r'q'], r'The local decay rate of a profile of dirac16complex along $\sigma$ at the frequency $\omega$, $q = \sqrt{m_\Psi^2 - \omega^2\mathrm{e}^{2H\lvert\sigma\rvert}}$ (imaginary beyond the turning point, where the profile oscillates).', r'GeV', '', r'DERIVED')
add(r'psigma', r'p_\sigma', [r'p_{\sigma}'], r'The momentum along the hidden direction (local wave number of a profile along $\sigma$).', r'GeV', '', r'DERIVED')
add(r'kappavec', r'\vec\kappa', [r'\vec{\kappa}'], r'A momentum along the extra times (three components); the fields of UM-4 have $\vec\kappa = 0$.', r'GeV', '', r'DERIVED')
add(r'muX', r'\mu_X,\ \mu_{\mathrm{L}},\ \mu_{\mathrm{R}}', [r'\mu_{X}', r'\mu_{\mathrm{L}}', r'\mu_{\mathrm{R}}'], r'The dimensionless strengths of the fold for the left-handed and right-handed halves of dirac16complex, set by the mean fields of the Standard Model at the fold: the jump of the profile across the fold is the exponential of $\gamma^{(0)}(\mu_{\mathrm{L}}P_{\mathrm{L}} + \mu_{\mathrm{R}}P_{\mathrm{R}})$; negative values attract.', r'dimensionless', '', r'DERIVED')
add(r'mean', r'\langle\cdots\rangle', [], r'The mean (expectation) value of an operator in the state of the medium (the vacuum, a plasma, the Kohn-Sham state).', '', '', r'STANDARD')
add(r'Gsq', r'\langle G^2\rangle', [], r'The mean square of the gluon field strength, $\langle G^A_{\mu\nu}G^{A\mu\nu}\rangle$ (the gluon condensate in the QCD vacuum, a thermal value in the plasma).', r'GeV$^4$', '', r'STANDARD')
add(r'Wsq', r'\langle W^2\rangle', [], r'The mean square of the $SU(2)$ field strength, $\langle W^I_{\mu\nu}W^{I\mu\nu}\rangle$.', r'GeV$^4$', '', r'STANDARD')
add(r'Bsq', r'\langle B^2\rangle', [], r'The mean square of the hypercharge field strength, $\langle B_{\mu\nu}B^{\mu\nu}\rangle$.', r'GeV$^4$', '', r'STANDARD')
add(r'nf', r'n_f', [r'n_{f}'], r'The number density of the Standard-Model fermions of kind $f$ (particles minus antiparticles, summed over generations and gauge components), the time component of the mean current $\langle J_f^\mu\rangle$ in the rest frame of the medium.', r'GeV$^3$', '', r'STANDARD')
add(r'qb', r'q_{\mathrm{b}}', [r'q_{\mathrm{b}}'], r'The inverse width of a state of dirac16complex at the fold: inside the turning point its profile falls as $\mathrm{e}^{-q_{\mathrm{b}}\lvert\sigma\rvert}$.', r'GeV', '', r'DERIVED')
add(r'varsigma', r'\varsigma', [r'\varsigma', r'\varsigma_{-}'], r'The auxiliary variable of the bound-state condition, $\varsigma = \sqrt{\mu_{\mathrm{L}}\mu_{\mathrm{R}}}$ ($\varsigma_- = \sqrt{-\mu_{\mathrm{L}}\mu_{\mathrm{R}}}$ when $\mu_{\mathrm{L}}\mu_{\mathrm{R}} < 0$).', r'dimensionless', '', r'DERIVED')
add(r'omegab', r'\omega_{\mathrm{b}}', [r'\omega_{\mathrm{b}}'], r'The energy at zero momentum of the state of dirac16complex at the fold in the limit $H \to 0$ (the bound state of UM-3): the particle $\chi$ of UM-4 has the mass $\omega_{\mathrm{r}} = \omega_{\mathrm{b}}(1 - H/(2q_{\mathrm{b}})) + \dots$, equal to $\omega_{\mathrm{b}}$ up to the relative correction $H/(2q_{\mathrm{b}})$.', r'GeV', '', r'DERIVED')
add(r'ns', r'n_{\mathrm{s}}', [r'n_{\mathrm{s}}'], r'The scalar density of dirac16complex in the Kohn-Sham state, $n_{\mathrm{s}} = \langle\bar\Psi\Psi\rangle = \mathrm{tr}\,\mathcal{N}$.', r'GeV$^7$', '', r'DERIVED')
add(r'Nmat', r'\mathcal{N}', [r'\mathcal{N}'], r'The one-body density matrix of dirac16complex, $\mathcal{N} = \sum_o\mathsf{n}_o\varphi_o\bar\varphi_o$ (a $16 \times 16$ matrix at each point).', r'GeV$^7$', '', r'DERIVED')
add(r'KSorb', r'\varphi_o,\ \bar\varphi_o', [r'\varphi', r'\bar{\varphi}'], r'A Kohn-Sham orbital of dirac16complex (a single-particle solution of the Kohn-Sham equation: the Dirac equation of dirac16complex with the mean field of the gas added to its mass) and its Dirac adjoint.', r'GeV$^{7/2}$', '', r'RECORD')
add(r'nocc', r'\mathsf{n}_o', [r'\mathsf{n}'], r'The occupation of the Kohn-Sham orbital $o$ (between 0 and 1).', r'dimensionless', '', r'RECORD')
add(r'Eorb', r'E', [r'E'], r'An energy: $E_o$ the energy of the Kohn-Sham orbital $o$; in the neutrino sector the energy of a neutrino.', r'GeV', '', r'STANDARD')
add(r'muPsi', r'\mu_\Psi', [r'\mu_{\Psi}'], r'The chemical potential of dirac16complex.', r'GeV', '', r'DERIVED')
add(r'TPsiT', r'\mathsf{T}_\Psi', [r'\mathsf{T}_{\Psi}'], r'The temperature of dirac16complex.', r'GeV', '', r'DERIVED')
add(r'QPsi', r'Q_\Psi', [r'Q_{\Psi}'], r'The conserved charge of dirac16complex (the Noether charge of a change of the phase of $\Psi$ by a constant), a Krein form (indefinite); as written it is the charge per unit coordinate volume of the extra times, on which no field depends.', r'GeV$^3$', '', r'DERIVED')
add(r'Bkrein', r'\mathfrak{B}', [r'\mathfrak{B}'], r'The Krein operator, $\mathfrak{B} = \mathrm{i}\sigma_{16}\gamma^{(4)}$: a Hermitian involution with the signature (8, 8); $\Psi^\dagger\mathfrak{B}\Psi$ is the charge density.', r'dimensionless', '', r'DERIVED')
add(r'Qorb', r'\mathcal{Q}_o', [r'\mathcal{Q}'], r'The charge $Q_\Psi$ (the Krein charge) of the single-particle state $o$ of dirac16complex, a Kohn-Sham orbital or a mode: $+1$ or $-1$ for a normalised state.', r'dimensionless', '', r'DERIVED')
add(r'chiKS', r'\chi_o(\sigma),\ \bar\chi_o', [r'\chi_{o}', r'\bar{\chi}_{o}', r'\chi_{p}', r'\chi_{1}'], r'The profile of the occupied Kohn-Sham orbital $o$ ($o = 1, \dots, 4$, the four positive-energy states of the level at the fold) of a homogeneous gas of the particles $\chi$ at rest on the static block: a 16-component spinor function of $\sigma$; the orbital of each particle is $\mathrm{e}^{\frac72H\lvert\sigma\rvert}\chi_o(\sigma)\mathrm{e}^{-\mathrm{i}\omega x_4}$ divided by the square root of the volume of ordinary space and of $V_*$; normalised to the Krein charge $-1$ with the measure of UM-4, $\int\mathrm{d}\sigma\,\mathrm{e}^{H\lvert\sigma\rvert}\chi_o^\dagger\mathfrak{B}\chi_o = -1$; $\bar\chi_o = \chi_o^\dagger\sigma_{16}$ is its Dirac adjoint.', r'GeV$^{1/2}$', '', r'DERIVED')
add(r'GKS', r'G_{\mathrm{KS}}', [r'G_{\mathrm{KS}}'], r'The dimensionless strength of the self-interaction of the gas of particles $\chi$ in the Kohn-Sham states: the self-coupling $\lambda_\Psi$ times the number density $n_\chi$ of the particles on the fold divided by the volume $V_*$ of the extra times, $G_{\mathrm{KS}} = \lambda_\Psi n_\chi/V_*$ (in units of $m_\Psi$ when numbers are given).', r'dimensionless', r'$10^{-6}$ to 0.5 in the solutions', r'DERIVED')
add(r'Mmean', r'\mathcal{M}(\sigma)', [r'\mathcal{M}'], r'The mean field of the self-interaction in the Kohn-Sham equation of the gas: the $16 \times 16$ matrix $\lambda_\Psi(n_{\mathrm{s}}\mathbf{1} - \mathcal{N})$ at each $\sigma$, which adds to the mass $m_\Psi$; positive (repulsive) for $\lambda_\Psi > 0$.', r'GeV', '', r'DERIVED')
add(r'rhohat', r'\hat\rho(\sigma)', [r'\hat{\rho}'], r'The scalar density of the occupied orbitals, $\hat\rho = \frac14\sum_o\bar\chi_o\chi_o$ (per particle); the scalar density of the gas is $n_{\mathrm{s}} = (n_\chi/V_*)\,\mathrm{e}^{7H\lvert\sigma\rvert}\hat\rho$.', r'GeV', '', r'DERIVED')
add(r'rhohatL', r'\hat\rho_{\mathrm{L}}', [r'\hat{\rho}_{\mathrm{L}}'], r'The scalar density of the left-handed half of the occupied orbitals, $\hat\rho_{\mathrm{L}} = \frac14\sum_o\bar\chi_oP_{\mathrm{L}}\chi_o$; at the fold the mean of its values on the two sides.', r'GeV', '', r'DERIVED')
add(r'rhohatL0', r'\hat\rho_{\mathrm{L}0}', [r'\hat{\rho}_{\mathrm{L}0}'], r'The left-handed scalar density $\hat\rho_{\mathrm{L}}$ of the state at the fold without the self-interaction and without the Higgs feedback.', r'GeV', '', r'DERIVED')
add(r'Nhat', r'\hat{\mathcal{N}}(\sigma)', [r'\hat{\mathcal{N}}'], r'The one-body density matrix of the occupied orbitals, $\hat{\mathcal{N}} = \frac14\sum_o\chi_o\bar\chi_o$ (a $16 \times 16$ matrix at each $\sigma$, per particle); the density matrix of the gas is $\mathcal{N} = (n_\chi/V_*)\,\mathrm{e}^{7H\lvert\sigma\rvert}\hat{\mathcal{N}}$.', r'GeV', '', r'DERIVED')
add(r'Eint', r'\mathsf{E}_{\mathrm{int}}', [r'\mathsf{E}_{\mathrm{int}}'], r'The interaction energy per particle of the gas of $\chi$: the mean self-interaction energy $\frac{\lambda_\Psi}{2}(n_{\mathrm{s}}^2 - \mathrm{tr}\,\mathcal{N}^2)$ integrated across the hidden direction, per particle.', r'GeV', '', r'DERIVED')
add(r'epsp', r'\epsilon_{\mathrm{p}}', [r'\epsilon_{\mathrm{p}}'], r'The energy per particle of the gas of $\chi$: the orbital energy minus the interaction energy per particle, which the orbital energy counts twice.', r'GeV', '', r'DERIVED')
add(r'wchi', r'w_\chi', [r'w_{\chi}'], r'The equation of state of the gas of the particles $\chi$: its pressure divided by its energy density, $w_\chi = P_{\mathrm{KS}}/(n_\chi\epsilon_{\mathrm{p}})$ (0 for cold dark matter, $-1$ for a vacuum energy).', r'dimensionless', '', r'DERIVED')
add(r'PKS', r'P_{\mathrm{KS}}', [r'P_{\mathrm{KS}}'], r'The pressure of the gas of $\chi$ along ordinary space in the Kohn-Sham state: the particles are at rest, so it is the mean self-interaction, $P_{\mathrm{KS}} = n_\chi\mathsf{E}_{\mathrm{int}}$.', r'GeV$^4$', '', r'DERIVED')
add(r'muL0', r'\mu_{\mathrm{L}0}', [r'\mu_{\mathrm{L}0}'], r'The strength $\mu_{\mathrm{L}}$ of the fold for the left-handed half without the feedback of the gas on the Higgs field.', r'dimensionless', r'$-0.6$ in the solutions', r'DERIVED')
add(r'kappaH', r'\kappa_{\mathrm{H}}', [r'\kappa_{\mathrm{H}}'], r'The strength of the Higgs-portal loop of the gas: the gas without the feedback changes the local $v_{\mathrm{loc}}^2$ at the fold by the factor $1 - \kappa_{\mathrm{H}}$, $\kappa_{\mathrm{H}} = c_\Phi n_\chi\hat\rho_{\mathrm{L}0}(0)/(\lambda v^2V_*)$; negative where the Higgs portal binds the fold ($c_\Phi < 0$, $\hat\rho_{\mathrm{L}0}(0) > 0$): the gas raises $v_{\mathrm{loc}}^2$.', r'dimensionless', r'$-0.3$ in the test of the loop', r'ASSUMED (the value), DERIVED (the sign)')
add(r'Delta', r'\Delta', [r'\Delta'], r'A change, difference or small variation of the quantity that follows (for example an interval of the time, a perturbation of a density, a difference of two squared masses, or an addition to an effective number of species).', '', '', r'STANDARD')
add(r'geff', r'g_{k,\mathrm{eff}}', [r'g_{1,\mathrm{eff}}', r'g_{2,\mathrm{eff}}', r'g_{3,\mathrm{eff}}', r'g_{k,\mathrm{eff}}'], r'The effective (canonically normalised) gauge couplings of the fold when the fold factor is $\mathcal{Z}$, $g_{k,\mathrm{eff}} = g_k/\sqrt{\mathcal{Z}}$ ($k = 1, 2, 3$): the kinetic terms of the massless modes of the gauge fields of the bulk carry the volume of the extra times as the terms of the fold do.', r'dimensionless', '', r'DERIVED')
add(r'lameff', r'\lambda_{\mathrm{eff}}', [r'\lambda_{\mathrm{eff}}'], r'The effective quartic Higgs coupling, $\lambda/\mathcal{Z}$.', r'dimensionless', '', r'DERIVED')
add(r'Yeff', r'\mathcal{Y}_{\mathrm{eff}}', [r'\mathcal{Y}_{\mathrm{eff}}'], r'The effective Yukawa matrices, $\mathcal{Y}/\sqrt{\mathcal{Z}}$ (for each of $\mathcal{Y}^{u}, \mathcal{Y}^{d}, \mathcal{Y}^{e}, \mathcal{Y}^{\nu}$).', r'dimensionless', '', r'DERIVED')
add(r'GNeff', r'G_{\mathrm{N,eff}}', [r'G_{\mathrm{N,eff}}'], r'The effective Newton constant of the fold, $G_{\mathrm{N}}/\mathcal{Z}$.', r'GeV$^{-2}$', '', r'DERIVED')
add(r'GN', r'G_{\mathrm{N}}', [r'G_{\mathrm{N}}'], r'Newton’s constant of four-dimensional gravity (the gravity of our world, on the fold), $G_{\mathrm{N}} = 1/M_{\mathrm{Pl}}^2$ with the Planck mass $M_{\mathrm{Pl}} = 1.221\times10^{19}$ GeV.', r'GeV$^{-2}$', r'$6.708\times10^{-39}$ GeV$^{-2}$', r'STANDARD')
