add(r'mZ', r'm_{\mathrm{Z}}', [r'm_{\mathrm{Z}}'], r'The mass of the Z boson.', r'GeV', r'91.19 GeV ($\mathcal{A} = 0$)', r'STANDARD')
add(r'GF', r'G_{\mathrm{F}}', [r'G_{\mathrm{F}}'], r'The Fermi constant, $G_{\mathrm{F}} = 1/(\sqrt2\,v^2)$ in the Standard-Model vacuum (its measured value); in the equations of the neutrino flavours it stands for the local Fermi constant of the ad hoc vacuum.', r'GeV$^{-2}$', r'$1.1664\times10^{-5}$ GeV$^{-2}$', r'STANDARD')
add(r'mh', r'm_h', [r'm_{h}'], r'The mass of the Higgs boson.', r'GeV', r'125.25 GeV (Particle Data Group 2022)', r'STANDARD')
add(r'Aphoton', r'A_\mu', [r'A'], r'The photon field of the fold (canonically normalised): the massless combination of the massless modes of $W^1, W^2, W^3$ and $B$ that the Higgs vacuum leaves massless; a field of the bulk whose zero mode travels at the speed of light.', r'GeV', '', r'STANDARD')
add(r'nI', r'n^I', [r'n^{I}'], r'The unit isovector of the ad hoc vacuum, $n = (2\mathcal{A}v, 0, \mathcal{A}^2 - v^2)/(\mathcal{A}^2 + v^2)$, which fixes which combination of $W^1, W^2, W^3$ joins $B$ in the photon.', r'dimensionless', r'$(0, 0, -1)$ for $\mathcal{A} = 0$', r'DERIVED')
add(r'Umix', r'U_{f\mathrm{L}},\ U_{f\mathrm{R}}', [r'U_{u\mathrm{L}}', r'U_{u\mathrm{R}}', r'U_{d\mathrm{L}}', r'U_{d\mathrm{R}}', r'U_{e\mathrm{L}}', r'U_{e\mathrm{R}}', r'U_{\nu \mathrm{L}}', r'U_{\nu \mathrm{R}}'], r'The unitary $3 \times 3$ matrices that diagonalise the mass matrices of the up quarks, the down quarks, the charged leptons and the neutrinos (left-handed and right-handed rotations).', r'dimensionless', '', r'STANDARD')
add(r'mferm', r'm_u, \dots, m_3', [r'm_{u}', r'm_{c}', r'm_{t}', r'm_{d}', r'm_{s}', r'm_{b}', r'm_{e}', r'm_{\mu}', r'm_{\tau}', r'm_{1}', r'm_{2}', r'm_{3}'], r'The masses of the quarks ($m_u, m_c, m_t$; $m_d, m_s, m_b$), of the charged leptons ($m_e, m_\mu, m_\tau$) and of the three neutrino mass states ($m_1, m_2, m_3$, Dirac masses).', r'GeV', r'measured values; $\Delta m_{21}^2 = 7.41\times10^{-5}$ eV$^2$, $\lvert\Delta m_{31}^2\rvert = 2.511\times10^{-3}$ eV$^2$ in the computations of UM-4 (the global fit NuFIT 5.2 of the oscillation data, November 2022), $7.49\times10^{-5}$ and $2.513\times10^{-3}$ eV$^2$ in NuFIT 6.0 (2024); the lightest mass $m_1 = 0$ in the computations, below 23 meV by DESI DR2 with the CMB and NuFIT 6.0', r'STANDARD')
add(r'Ckm', r'V_{\mathrm{CKM}}', [r'V_{\mathrm{CKM}}'], r'The quark mixing matrix (Cabibbo-Kobayashi-Maskawa).', r'dimensionless', '', r'STANDARD')
add(r'Pmns', r'U_{\mathrm{PMNS}}', [r'U_{\mathrm{PMNS}}'], r'The lepton mixing matrix (Pontecorvo-Maki-Nakagawa-Sakata) of the three Dirac neutrinos; its entries $(U_{\mathrm{PMNS}})_{\alpha i}$ connect the flavour state $\nu_\alpha$ with the mass state $\nu_i$.', r'dimensionless', r'$\theta_{12} = 33.40^\circ$, $\theta_{23} = 49.14^\circ$, $\theta_{13} = 8.54^\circ$ (NuFIT 5.2, November 2022, normal ordering, the fit without the Super-Kamiokande atmospheric data); the Dirac phase is set to zero (ASSUMED; the fit prefers $197^\circ$)', r'STANDARD, ASSUMED (the phase)')
add(r'nugen', r'\nu_\alpha,\ \nu_i', [r'\nu', r'\bar{\nu}'], r'A neutrino field: $\nu_\alpha$ the flavour states (the flavour index runs over the electron, muon and tau flavours), $\nu_i$ the mass states ($i = 1, 2, 3$).', r'GeV$^{3/2}$', '', r'STANDARD')
add(r'LCC', r'\mathcal{L}_{\mathrm{CC}}', [r'\mathcal{L}_{\mathrm{CC}}'], r'The charged-current interaction of the quarks and leptons with the $W$ bosons.', r'GeV$^4$', '', r'STANDARD')
add(r'hatferm', r'\hat u_{\mathrm{L}},\ \hat d_{\mathrm{L}},\ \hat e_{\mathrm{L}\alpha}', [r'\bar{\hat u}_{\mathrm{L}}', r'\hat{u}_{\mathrm{L}}', r'\hat{d}_{\mathrm{L}}', r'\hat{e}_{\mathrm{L}\alpha}'], r'The left-handed quarks and charged leptons in the mass basis ($\hat e_{\mathrm{L}\alpha}$ the charged lepton of flavour $\alpha$).', r'GeV$^{3/2}$', '', r'STANDARD')
add(r'gport', r'\mathfrak{g}_{\Phi},\ \mathfrak{g}_{G},\ \mathfrak{g}_{f},\ \mathfrak{g}_{h\chi}', [r'\mathfrak{g}_{\Phi}', r'\mathfrak{g}_{G}', r'\mathfrak{g}_{f}', r'\mathfrak{g}_{h\chi}'], r'The four-dimensional couplings of the particles $\chi$ of dirac16complex to the Standard Model: to $\Phi^\dagger\Phi$, to the gluon kinetic density, to the number densities of the fermions of kind $f$, and the Yukawa coupling of the Higgs boson to $\chi$.', r'$\mathfrak{g}_{\Phi}$: GeV$^{-1}$; $\mathfrak{g}_{G}$: GeV$^{-3}$; $\mathfrak{g}_{f}$: GeV$^{-2}$; $\mathfrak{g}_{h\chi}$: dimensionless', '', r'DERIVED')
add(r'vhat', r'\hat v,\ \hat v^\mu', [r'\hat{v}'], r'The direction of motion of a neutrino: the unit vector $\hat v = \vec p/\lvert\vec p\rvert$ ($\hat v_{\vec p}$, $\hat v_{\vec q}$ for the momenta $\vec p$, $\vec q$), and the four-vector $\hat v^\mu = (1, \hat v)$ in the order $(x_4; x_1, x_2, x_3)$; $\mathrm{d}^2\hat v$ is the element of solid angle of the directions.', r'dimensionless', '', r'STANDARD')
add(r'nablavec', r'\vec\nabla', [r'\vec{\nabla}'], r'The gradient along ordinary space, $\vec\nabla = (\partial_{x_1}, \partial_{x_2}, \partial_{x_3})$ (in the local frame of the medium).', r'1/length', '', r'STANDARD')
add(r'pvec', r'\vec p', [r'\vec{p}'], r'The momentum of a neutrino (three components along ordinary space, in the rest frame of the medium); $\lvert\vec p\rvert = E$ for a neutrino of negligible mass.', r'GeV', '', r'STANDARD')
add(r'qvec', r'\vec q', [r'\vec{q}'], r'The momentum of another neutrino of the medium (the integration variable of the neutrino-neutrino potential); $\mathrm{d}^3\vec q$ its volume element.', r'GeV', '', r'STANDARD')
add(r'rhoflav', r'\varrho_{\vec p},\ \bar\varrho_{\vec p}', [r'\varrho', r'\bar{\varrho}'], r'The $3 \times 3$ flavour density matrices of the neutrinos and of the antineutrinos of momentum $\vec p$ in the flavour basis (electron, muon, tau): the diagonal entries are the occupation numbers of the three flavours, the off-diagonal entries the coherence between the flavours; $\bar\varrho$ is defined with the flavour indices in the reversed order, so that it obeys an equation of the same form.', r'dimensionless', '', r'STANDARD')
add(r'Hflav', r'\mathsf{H}_{\vec p},\ \bar{\mathsf{H}}_{\vec p}', [r'\mathsf{H}', r'\bar{\mathsf{H}}'], r'The flavour Hamiltonians ($3 \times 3$ Hermitian matrices) of the neutrinos and of the antineutrinos of momentum $\vec p$.', r'GeV', '', r'STANDARD')
add(r'Ccoll', r'\mathcal{C}_{\vec p},\ \bar{\mathcal{C}}_{\vec p}', [r'\mathcal{C}', r'\bar{\mathcal{C}}'], r'The collision terms ($3 \times 3$ matrices) of the neutrinos and the antineutrinos of momentum $\vec p$: the rates of change of $\varrho_{\vec p}$ and $\bar\varrho_{\vec p}$ by emission, absorption, scattering and pair processes with the matter.', r'GeV', '', r'STANDARD')
add(r'Mmass', r'\mathsf{M}^2', [r'\mathsf{M}'], r'The diagonal matrix of the squared masses of the three neutrino mass states, $\mathsf{M}^2 = \mathrm{diag}(m_1^2, m_2^2, m_3^2)$ ($\mathsf{M}$ appears only squared).', r'GeV$^2$ (of $\mathsf{M}^2$)', '', r'STANDARD')
add(r'Vm', r'\mathsf{V}_{\mathrm{m}}', [r'\mathsf{V}_{\mathrm{m}}'], r'The matter potential of the neutrinos (a $3 \times 3$ matrix in flavour space) from their forward scattering on the electrons, positrons and neutrons of the medium.', r'GeV', '', r'STANDARD')
add(r'Vnunu', r'\mathsf{V}_{\nu\nu}', [r'\mathsf{V}_{\nu \nu}'], r'The neutrino-neutrino potential (a $3 \times 3$ matrix in flavour space) from the forward scattering of a neutrino on the other neutrinos and antineutrinos of the medium; it depends on their flavour content and their directions.', r'GeV', '', r'STANDARD')
add(r'VPsi', r'V_\Psi', [r'V_{\Psi}'], r'The potential energy that dirac16complex gives every neutrino through the current portal of the lepton doublets, $V_\Psi = \mathcal{V}^{\ell}_{x_4}$ (the same for the three flavours).', r'GeV', '', r'DERIVED')
add(r'vloc', r'v_{\mathrm{loc}}', [r'v_{\mathrm{loc}}'], r'The local value of the electroweak vacuum, $v_{\mathrm{loc}}^2 = 2\langle\Phi^\dagger\Phi\rangle$: it sets the local masses of the quarks and leptons (each mass times $v_{\mathrm{loc}}/v$) and the local Fermi constant; $v_{\mathrm{loc}} = v$ in the Standard-Model vacuum.', r'GeV', r'$v$ in the late universe outside dense dirac16complex', r'DERIVED')
add(r'GFloc', r'G_{\mathrm{F,loc}}', [r'G_{\mathrm{F,loc}}'], r'The local Fermi constant, $G_{\mathrm{F,loc}} = 1/(\sqrt2\,v_{\mathrm{loc}}^2)$ ($= G_{\mathrm{F}}$ where $v_{\mathrm{loc}} = v$).', r'GeV$^{-2}$', '', r'DERIVED')
add(r'ne', r'n_e', [r'n_{e}'], r'The number density of electrons (bound and free; in a supernova all are free, in the recombining universe $x_{\mathrm{e}}n_e$ is the density of the free electrons).', r'GeV$^3$ (cm$^{-3}$)', '', r'STANDARD')
add(r'nebar', r'n_{\bar e}', [r'n_{\bar e}'], r'The number density of positrons.', r'GeV$^3$', '', r'STANDARD')
add(r'nn', r'n_n', [r'n_{n}'], r'The number density of neutrons.', r'GeV$^3$', '', r'STANDARD')
add(r'thetamix', r'\theta', [r'\theta'], r'The vacuum mixing angle of two neutrino flavours (in the two-flavour description of a resonance, one of the three angles $\theta_{12}, \theta_{13}, \theta_{23}$ of $U_{\mathrm{PMNS}}$).', r'dimensionless', '', r'STANDARD')
add(r'thetam', r'\theta_{\mathrm{m}}', [r'\theta_{\mathrm{m}}'], r'The mixing angle of two neutrino flavours in matter.', r'dimensionless', '', r'STANDARD')
add(r'mmass', r'm', [r'm', r'm_{21}', r'm_{31}', r'm_{32}'], r'A mass: $m_i$ the mass of the neutrino mass state $i$; $\Delta m_{ij}^2 = m_i^2 - m_j^2$ the squared-mass difference of the states $i$ and $j$ ($\Delta m_{21}^2$, $\Delta m_{31}^2$, $\Delta m_{32}^2$); $\Delta m^2$ without labels the difference of the two states of a resonance, $m_2^2 - m_1^2$, multiplied by $v_{\mathrm{loc}}^2/v^2$ where this differs from 1; $m$ without a label the mass of a mode of a field of the bulk as the fold sees it, $m^2 = \omega^2 - k^2$; for the W and Z bosons their complex pole mass, $m^2 = m_0^2 - \mathrm{i}m_0\Gamma_{\mathrm{bulk}}$ to the leading order; in the relic abundance of the particles $\chi$ their mass.', r'GeV', '', r'STANDARD')
add(r'VCC', r'V_{\mathrm{CC}}', [r'V_{\mathrm{CC}}'], r'The charged-current matter potential of the electron neutrinos (forward scattering on electrons through $W$ exchange).', r'GeV', '', r'STANDARD')
add(r'neres', r'n_{e,\mathrm{res}}', [r'n_{e,\mathrm{res}}'], r'The electron density at which the flavour conversion in matter is resonant (the Mikheyev-Smirnov-Wolfenstein resonance).', r'GeV$^3$', '', r'STANDARD')
add(r'PLZ', r'P_{\mathrm{LZ}}', [r'P_{\mathrm{LZ}}'], r'The probability that a neutrino jumps between the eigenstates of matter at the resonance (Landau-Zener); $P_{\mathrm{LZ}} = 0$ is an adiabatic resonance.', r'dimensionless', '', r'STANDARD')
